"""Generate audited pooled panels for the single frozen nested correction family."""
import argparse,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from tuning_summary import summarize,select


def main():
    ap=argparse.ArgumentParser();ap.add_argument('run',type=Path);a=ap.parse_args();run=a.run.resolve();d=json.loads((run/'result.json').read_text());audit=json.loads((run/'audit.json').read_text());assert audit['passed'] and d['complete'];cfg=d['config']
    panel=dict(pde='poisson2d',status='audited final nested-correction family on42already-opened development cases; no final confirmation',source_commit=d['provenance']['commit'],job_id=d['provenance']['job_id'],provenance=d['provenance'],config=cfg,
        run_path=str(run),source_result_path=str(run/'result.json'),audit_path=str(run/'audit.json'),archive_path=str(run/'ARCHIVE.json'),cleanup_path=str(run/'cleanup.json'),source_result_sha256=audit['result_sha256'],archive_sha256=audit['archive_sha256'],remote_deleted=audit['remote_deleted'],
        checkpoints=d['checkpoints'],basis=d['basis'],training_only_basis_audit=audit['training_only_basis'],cohort=d['cohort'],validation_status=cfg['validation_status'],primary_model=cfg['primary_model'],matched_control='r128_q0',frozen_control='original_relative',timed_invocations=len(d['rows']),timing_statistic='pooled median over equal-count case/repetition samples; every repetition retained',timing_scope=d['rows'][0].get('timing_scope',cfg['online_contract']),
        error_definition='worst current-relative full-field L2 versus restricted2048 FD-DST truth; empirical1024 refinement allowance retained separately',groups=[],limitations=['All42 sources are opened development, not independent final validation','One frozen32-direction basis with nested prefixes;32 predeclared primary, no further search','Intervention combines added linear correction capacity and exact analytic elimination','Both full and reduced normalized gradients gate numerical validity; their denominators differ','Final Jacobian-rank and gradient diagnostics charged to every paired neural timing; no elapsed-time comparison across jobs','Correction prefixes share the unchanged128-dimensional bank;3% bank target remains separate from5% physical eligibility','Direct DST remains a same-job FOM control; no universal FOM advantage'])
    for group in ['all','existing_development','new_development']:
        cases=[i for i,g in enumerate(d['cohort']['groups']) if group=='all' or g==group];entry=dict(group=group,cases=len(cases),meshes=[])
        for n in cfg['intervals']:
            rows=[r for r in d['rows'] if r['case'] in cases and r['intervals']==n];methods=summarize(rows,cfg);bank={}
            for model in cfg['trained_model_ids']:
                rs=[r for r in rows if r['method']==model];m=methods[model];base=cfg['method_base_model'][model];m.update(base_model=base,checkpoint_sha256=rs[0]['checkpoint_sha256'],requested_modes=rs[0]['requested_modes'],retained_modes=rs[0]['retained_modes'],all_bank_ranks_valid=all(r['bank_rank_valid'] for r in rs),correction_count=rs[0]['correction_count'],nominal_latent_dimension=rs[0]['nominal_latent_dimension'],nonlinear_optimizer_dimension=16,latent_dimension=rs[0]['nominal_latent_dimension'],feature_count=64 if base=='original_relative' else 128)
                m.update(full_stationary_invocations=sum(r['stationary'] for r in rs),reduced_stationary_invocations=sum(r['reduced_stationary'] for r in rs),both_stationary_invocations=sum(r['stationary'] and r['reduced_stationary'] for r in rs),maximum_full_stationarity=max(r['stationarity'] for r in rs),maximum_reduced_stationarity=max(r['reduced_stationarity'] for r in rs),all_projected_jacobian_ranks_valid=all(r['projected_jacobian_rank_valid'] for r in rs),minimum_projected_jacobian_rank=min(r['projected_jacobian_rank'] for r in rs),all_linear_recoveries_valid=all(r['linear_recovery_backward_error']<=cfg['linear_backward_error_limit'] for r in rs),solver_valid_invocations=sum(r['solver_valid'] for r in rs),all_stationary=all(r['solver_valid'] for r in rs))
                o=[o for o in d['oracles'] if o['base_model']==base and o['intervals']==n and o['case'] in cases];bank[model]=dict(base_model=base,shared_unchanged_bank=True,worst_same_grid_relative_error=max(x['same_grid_relative_error'] for x in o),worst_physical_error=max(x['physical_error'] for x in o),all_ranks_valid=all(x['rank_valid'] for x in o),proposed_bank_target=cfg['proposed_gates']['bank_worst_relative_error'],passes_proposed_bank_target=all(x['rank_valid'] and x['same_grid_relative_error']<=cfg['proposed_gates']['bank_worst_relative_error'] for x in o))
                m['gpu_speedup_vs_frozen']=methods['original_relative']['gpu_median_ms']/m['gpu_median_ms'];m['host_speedup_vs_frozen']=methods['original_relative']['host_median_ms']/m['host_median_ms'];m['gpu_speedup_vs_uncorrected']=methods['r128_q0']['gpu_median_ms']/m['gpu_median_ms'];m['host_speedup_vs_uncorrected']=methods['r128_q0']['host_median_ms']/m['host_median_ms']
            passing=[m for m in methods if m.startswith('cg_') and methods[m]['all_cases_pass_target']];cg=min(passing,key=lambda m:methods[m]['gpu_median_ms']) if passing else None
            for model in cfg['trained_model_ids']:
                m=methods[model];m.update(speedup_vs_tight_cg=methods['cg_1e-06']['gpu_median_ms']/m['gpu_median_ms'],speedup_vs_fastest_passing_cg=methods[cg]['gpu_median_ms']/m['gpu_median_ms'] if cg else None,speedup_vs_dst=methods['dst']['gpu_median_ms']/m['gpu_median_ms'],no_gpu_cost_regression_vs_frozen=m['gpu_median_ms']<=methods['original_relative']['gpu_median_ms'],no_host_cost_regression_vs_frozen=m['host_median_ms']<=methods['original_relative']['host_median_ms'])
            entry['meshes'].append(dict(intervals=n,methods=methods,bank_diagnostics=bank,fastest_passing_cg=cg,selection=select(methods,cfg['trained_model_ids']),selection_scope='descriptive among this one fixed family;32 remains predeclared primary'))
        panel['groups'].append(entry)
    (run/'panel.json').write_text(json.dumps(panel,indent=2)+'\n')
    lines=['# Final Poisson correction family','', 'Audited frozen correction-family results on already-opened development cases. These are a combined change in linear capacity and analytic elimination; no final-cohort claim.','']
    for group in panel['groups']:
        lines += ['## '+group['group'],'','| Intervals | Method | GPU ms | Host ms | Worst error % | Adjusted error % | Invalid calls | Pass5% | Bank pass3% |','|---:|---|---:|---:|---:|---:|---:|---|---|']
        for mesh in group['meshes']:
            for method,m in mesh['methods'].items():
                b=mesh['bank_diagnostics'].get(method);lines.append(f"| {mesh['intervals']} | {method} | {m['gpu_median_ms']:.6f} | {m['host_median_ms']:.6f} | {100*m['worst_relative_error']:.6f} | {100*m['worst_adjusted_relative_error']:.6f} | {m['invalid_invocations']} | {m['all_cases_pass_target']} | {b['passes_proposed_bank_target'] if b else 'n/a'} |")
        lines.append('')
    lines+=['## Glossary','','Intervals: cells per axis, so nodes per axis are one larger. GPU ms: pooled median timed device-query milliseconds. Host ms: input, device and output time. Worst error: largest current-relative full-field discrepancy against the fine numerical reference. Adjusted error: conservative error including measured reference refinement. Invalid calls: invocations failing the declared numerical gates. Pass5%: every case/repetition passes adjusted physical error, refinement and numerical gates. Bank pass3%: full-bank projection diagnostic meets the separate proposed target. Correction counts8/16/32 add linear coordinates to the same16-variable nonlinear head; q0 is the uncorrected model. CG: iterative conjugate gradients with named relative residual tolerance. DST: direct sine-transform FOM. Existing development: original30 sources; new_development: later12 sources, already opened before this experiment.']
    (run/'summary.md').write_text('\n'.join(lines)+'\n');print(run/'panel.json')


if __name__=='__main__':main()
